    gaps={'missing_or_not_reexecuted':[{'item':'Historical generation Pillow version','status':'genuinely unrecorded','impact':'Do not assert historical version pin or universal bit parity; current source branch and discriminating captured sample verified.'},{'item':'Compiled deformable-attention extension bit parity','status':'unverified by original debug-core runner','impact':'Exact source/debug backend identified; no compiled-backend parity claim.'},{'item':'Fresh full116 native-pixel stage rematching','status':'not computed in this extension','impact':'Full116archived certificates reaggregated;16actual native windows freshly rematched. Full-cohort command and raw external contracts supplied.'},{'item':'New original-checkpoint image inference/full normalization','status':'not executed intentionally; completed archives reused','impact':'Actual executed runners/complete sources/observers/configs and checksum acquisition/preparation recipes supplied; archive readers are standalone.'},{'item':'Upstream common B/E model generation','status':'saved source predictions reused,not new inference','impact':'Actual sixpolicy execution all96 rerun; source-root B/E/geff/zarr generation inputs remain authorized external contracts.'},{'item':'Full native49 raw states in compact archive','status':'not bundled;four thresholded support members are explicit derivatives','impact':'Baseline all29mathematical matching exact; native16actual selected outputs+pixels supplied; optional full raw matching needs specified original state files.'},{'item':'Old extension config snapshots before final471fileconfig','status':'not all historical wrapping CONFIG snapshots retained','impact':'Old recorded config hashes retained; actual adapter snapshots,input byte hashes/output freezes remain. Final standalone pass uses supplied471fileconfig and full155record equality.'}],'not_missing':{'baseline_support_frames':5340,'pulse_prediction_arm_films':116,'pulse_archived_stage_arm_films':116,'pulse_stage_relation_arm_records':124372,'natural_baseline_reference_relations':31093,'common_policy_outputs':96,'full_policy_movie_outputs':87,'timing_movie_arm_tolerance_records':174,'CCA_movie_arm_records':87,'eligible_chain_permovie_records':29,'native_rematched_windows':16,'Figure4_actual_pixels_types_flags':True,'wrong_type_relation_crosswalk':123,'event_crosswalk_units':64,'chain_type_only_crosswalk':30},'all_outputs_local_only':True,'publication_permission_granted':False,'scientific_Major_closed_claim':False}
    write(HERE/'COVERAGE_GAPS.json',gaps)
    versions={}
