    write(HERE/'ARCHIVE_ENVIRONMENT.json',{'actual_checked_versions':versions,'reader_runtime':'Python3.13.12; no GPU needed','optional_inference_and_resize':'torch/torchvision/Pillow use separately supplied generator environment/source evidence','archive_optional_common_regeneration':'zarr/geff source-root inputs, no fresh training'})
    history={'primary_current_crosswalk':'identity_crosswalk_standalone_run04','superseded_crosswalks':{'identity_crosswalk_run01':'early candidate link rule superseded','identity_crosswalk_run02':'later outgoing-event assignment could overlink; superseded','identity_crosswalk_run03':'correct original-root result, reproduced by standalone_run04'},'failed_preserved':{'pulse-endpoint_run01':'Windows prediction key slash normalization missing; corrected run02 passed','common_generation_run01':'all96prediction generation/comparison completed; final bookkeeping Path type error; run02completed','standalone_clean_run01/division-overlays':'Missing copied helper needed only for source hash; corrected isolated standalone_clean_run02/division-overlays completed','standalone_record_comparison_run01':'87CCA input path relocations flagged; complete differences retained; run02explicitly preserves them while every scientific/hash field remains equal'},'standalone_pass':'all11routes success across clean_run01tenroutes+clean_run02division; no inference/normalization','configuration_snapshot_limit':'Old early wrapping configurations missing; final471fileconfig and actual frozen adapter/input/output snapshots supplied'}
    write(HERE/'EXECUTION_HISTORY.json',history)
    records={p.relative_to(HERE).as_posix():{'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(HERE.rglob('*')) if p.is_file() and p.name!='FINALIZED_LOCAL_ONLY.json' and '__pycache__' not in p.parts}
